alter table public.seo_locations
  add column if not exists tier text not null default 'C' check (tier in ('A', 'B', 'C')),
  add column if not exists content_profile jsonb not null default '{}'::jsonb;

alter table public.seo_local_pages
  add column if not exists quality_score integer not null default 0,
  add column if not exists duplicate_risk text not null default 'high' check (duplicate_risk in ('low', 'medium', 'high')),
  add column if not exists coverage_status text not null default 'none' check (coverage_status in ('none', 'limited', 'sufficient'));

create index if not exists seo_local_pages_quality_score_idx on public.seo_local_pages (quality_score);
create index if not exists seo_local_pages_duplicate_risk_idx on public.seo_local_pages (duplicate_risk);
create index if not exists seo_local_pages_coverage_status_idx on public.seo_local_pages (coverage_status);
create index if not exists seo_locations_tier_idx on public.seo_locations (tier);

create table if not exists public.seo_audit_log (
  id uuid primary key default gen_random_uuid(),
  seo_local_page_id uuid not null references public.seo_local_pages(id) on delete cascade,
  actor text not null,
  action text not null check (action in ('status_change', 'publish', 'unpublish')),
  previous_status text not null,
  new_status text not null,
  created_at timestamptz not null default timezone('utc', now())
);

alter table public.seo_audit_log enable row level security;

create policy "admins manage seo audit log"
  on public.seo_audit_log
  for all
  using ((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin')
  with check ((auth.jwt() -> 'app_metadata' ->> 'role') = 'admin');

insert into public.seo_locations (
  slug,
  name,
  province,
  region_label,
  tier,
  content_profile,
  intro_facts,
  local_characteristics,
  nearby_city_slugs,
  population_band,
  housing_notes,
  published,
  indexable,
  priority
)
