on conflict (slug) do update set
  name = excluded.name,
  province = excluded.province,
  region_label = excluded.region_label,
  tier = excluded.tier,
  content_profile = excluded.content_profile,
  intro_facts = excluded.intro_facts,
  local_characteristics = excluded.local_characteristics,
  nearby_city_slugs = excluded.nearby_city_slugs,
  population_band = excluded.population_band,
  housing_notes = excluded.housing_notes,
  published = excluded.published,
  indexable = excluded.indexable,
  priority = excluded.priority,
  updated_at = timezone('utc', now());

update public.seo_locations
set tier = case
  when slug in ('amsterdam','rotterdam','den-haag','utrecht','eindhoven','groningen','tilburg','breda','nijmegen','arnhem','haarlem','almere','zwolle','amersfoort') then 'A'
  when slug in ('maastricht','enschede','leiden','den-bosch','apeldoorn','deventer','alkmaar','ede','gouda','zoetermeer') then 'B'
  else coalesce(tier, 'C')
end;

update public.seo_local_pages
set
  quality_score = greatest(quality_score, 0),
  duplicate_risk = case when duplicate_risk in ('low', 'medium', 'high') then duplicate_risk else 'high' end,
  coverage_status = case when coverage_status in ('none', 'limited', 'sufficient') then coverage_status else 'none' end;
